(function() {var loader=document.getElementById("egoshev-logo-loader");if(loader&&document.body&&loader.parentNode!==document.body) {document.body.appendChild(loader);}
var btns=document.querySelectorAll("#egoshev-links-page .egoshev-btn, #egoshev-links-page .egoshev-social-link, #egoshev-links-page .egoshev-gift-btn");for(var i=0;i<btns.length;i++) {btns[i].addEventListener("touchstart",function() {this.style.transform="translateY(0) scale(0.98)";},{passive:true});btns[i].addEventListener("touchend",function() {var el=this;setTimeout(function() {el.style.transform="";},150);},{passive:true});}
try {var tildaFooter=document.querySelector(".t-footer");if(tildaFooter) tildaFooter.style.display="none";} catch(e) {}
setTimeout(function() {var loader=document.getElementById("egoshev-logo-loader");if(loader&&loader.parentNode) {loader.parentNode.removeChild(loader);}},2300);})();
